let Email = EmailEvents
| where TimeGenerated {TimeRange}
| summarize arg_max(TimeGenerated, *) by NetworkMessageId, RecipientEmailAddress;
let Top = Email | where EmailDirection == "Outbound" | summarize count() by SenderFromAddress | top 10 by count_ | project SenderFromAddress;
Email | where EmailDirection == "Outbound" and SenderFromAddress in (Top)
| summarize count() by SenderFromAddress, bin(TimeGenerated, {TimeRange:grain})

EmailPostDeliveryEvents
| where TimeGenerated {TimeRange}
| summarize count() by ActionType, ActionResult

let Email = EmailEvents
| where TimeGenerated {TimeRange}
| summarize arg_max(TimeGenerated, *) by NetworkMessageId, RecipientEmailAddress;
let Removed = EmailPostDeliveryEvents | where TimeGenerated {TimeRange} | where ActionResult =~ "Success" | distinct NetworkMessageId, RecipientEmailAddress;
Email
| where EmailDirection == "Inbound" and ThreatTypes has_any ("Phish", "Malware") and DeliveryLocation == "Inbox/folder"
| join kind=leftanti Removed on NetworkMessageId, RecipientEmailAddress
| project TimeGenerated, RecipientEmailAddress, SenderFromAddress, Subject, ThreatTypes, DetectionMethods, EmailActionPolicy, OrgLevelAction, UserLevelAction
| order by TimeGenerated desc

let Email = EmailEvents
| where TimeGenerated {TimeRange}
| summarize arg_max(TimeGenerated, *) by NetworkMessageId, RecipientEmailAddress;
let Internal = Email | where EmailDirection == "Inbound" | distinct RecipientDomain;
let Roots = Internal | extend Root = extract(@"([^.]+)\.[^.]+$", 1, RecipientDomain) | where strlen(Root) >= 4 | distinct Root;
Email
| where EmailDirection == "Inbound" and SenderFromDomain !in~ (Internal)
| extend SenderRoot = extract(@"([^.]+)\.[^.]+$", 1, tolower(SenderFromDomain))
| extend Norm = replace_strings(SenderRoot, dynamic(["rn", "vv", "0", "1", "3", "5", "-", "_"]), dynamic(["m", "w", "o", "l", "e", "s", "", ""]))
| extend k = 1 | join kind=inner (Roots | extend k = 1) on k
| where Norm contains Root and SenderFromDomain !endswith strcat(".", Root) 
| summarize Messages = count(), Recipients = dcount(RecipientEmailAddress), Delivered = countif(DeliveryAction == "Delivered"), Threats = make_set(ThreatTypes, 5), Subjects = make_set(Subject, 5) by SenderFromDomain, ImpersonatedRoot = Root
| order by Delivered desc

let Email = EmailEvents
| where TimeGenerated {TimeRange}
| summarize arg_max(TimeGenerated, *) by NetworkMessageId, RecipientEmailAddress;
let Prior = EmailEvents | where TimeGenerated between (ago(30d) .. todatetime('{TimeRange:start}')) | where EmailDirection == "Inbound" | distinct SenderFromDomain;
Email
| where EmailDirection == "Inbound" and SenderFromDomain !in (Prior)
| summarize Messages = count(), Recipients = dcount(RecipientEmailAddress), Delivered = countif(DeliveryAction == "Delivered"),
    WithThreats = countif(isnotempty(ThreatTypes)), FirstSeen = min(TimeGenerated), Subjects = make_set(Subject, 3) by SenderFromDomain
| order by Recipients desc
| take 200
